#!/usr/bin/env python3
# MANAGER_PF_RETENTION_FIX (v3) — TEK DOSYA. Onceki tum fix'leri kapsar + kohort tip kirilimini
# TOPTAN / TICARI (yalniz FILO TICARI) olarak ayirir, KURUM'u tamamen cikarir.
#  (1) /retention matris CASE → toptan/ticari/perakende/eticaret (+ Kurum haric),
#  (2) /retention-liste → hizli master_musteri + ayni yeni tip eslemesi (Tumu de Kurum'u saymaz),
#  (3) /konsantr-liste endpoint (konsantrasyon drill),
#  (4) guncel shell: cipler Toptan/Ticari/Perakende/E-ticaret/Tumu + CSV export + Kokpit link.
# Idempotent (her adim ayri guard, once-uygulanmis-mi kontrolu) + .bak + node --check + rollback.
# KULLANIM (Fatih): /opt/krb-assessment/ icine koy →
#   cd /opt/krb-assessment && python3 patch_retention_fix.py \
#     && docker build -t krb-assessment:secure . && docker compose up -d --force-recreate krb-assessment
import sys, subprocess, shutil, os, base64
SRC="/opt/krb-assessment/server_container.mjs"
SHELLD="/opt/krb-assessment/shells/manager_portfoyum.html"
ANCHOR='if (method === "GET" && path === "/api/saha/manager-portfoyum/ekran") {'
KMARK="MANAGER_PF_KONSANTR_LISTE"

OLD_MATRIX=r"""     typed AS (
        SELECT c.ilk_yil, c.yillar,
          CASE WHEN r.grup IN ('FILO TICARI','FILO TUKETICI','TOPTAN','KURUM','IHRACAT') THEN 'b2b'
               WHEN r.grup='.PERAKENDE' THEN 'perakende'
               WHEN r.grup='E-TICARET' THEN 'eticaret' ELSE 'diger' END tip
          FROM cust c LEFT JOIN bi_musteri_risk r ON r.tenant_id::text=$1::text AND r.muhatap_kodu=c.musteri_kodu
         WHERE c.ilk_yil >= 2022)"""
NEW_MATRIX=r"""     typed AS (
        SELECT c.ilk_yil, c.yillar,
          CASE WHEN r.grup='TOPTAN' THEN 'toptan'
               WHEN r.grup='FILO TICARI' THEN 'ticari'
               WHEN r.grup='.PERAKENDE' THEN 'perakende'
               WHEN r.grup='E-TICARET' THEN 'eticaret'
               WHEN r.grup='KURUM' THEN 'kurum' ELSE 'diger' END tip
          FROM cust c LEFT JOIN bi_musteri_risk r ON r.tenant_id::text=$1::text AND r.muhatap_kodu=c.musteri_kodu
         WHERE c.ilk_yil >= 2022 AND COALESCE(r.grup,'') <> 'KURUM')"""
OLD_SLOW=r"""  const r = await query(
    `WITH cust AS (
        SELECT f.musteri_kodu, min(extract(year from f.fatura_tarihi))::int ilk_yil,
               max(f.fatura_tarihi)::date son_alim, round(sum(f.satir_tutar))::bigint ciro_tum,
               bool_or(f.fatura_tarihi >= CURRENT_DATE - INTERVAL '12 months') aktif
          FROM bi_satis_faturalari f
         WHERE f.tenant_id::text=$1::text AND f.satir_tutar>0 AND f.fatura_tarihi IS NOT NULL
         GROUP BY 1),
     typed AS (
        SELECT c.*,
          CASE WHEN r.grup IN ('FILO TICARI','FILO TUKETICI','TOPTAN','KURUM','IHRACAT') THEN 'b2b'
               WHEN r.grup='.PERAKENDE' THEN 'perakende'
               WHEN r.grup='E-TICARET' THEN 'eticaret' ELSE 'diger' END tip
          FROM cust c LEFT JOIN bi_musteri_risk r ON r.tenant_id::text=$1::text AND r.muhatap_kodu=c.musteri_kodu)
     SELECT c.musteri_kodu, mm.musteri_adi AS firma, mm.sehir AS il,
            c.ciro_tum AS ciro_12, c.son_alim,
            count(*) OVER () AS toplam, sum(c.ciro_tum) OVER () AS ciro_toplam
       FROM typed c LEFT JOIN master_musteri mm ON mm.tenant_id::text=$1::text AND mm.musteri_kodu=c.musteri_kodu
      WHERE c.ilk_yil=$2 AND ($3='tumu' OR c.tip=$3) AND NOT c.aktif
      ORDER BY c.ciro_tum DESC NULLS LAST LIMIT 200`, [T, kohort, tip]);"""
