def apply(newsrc, bak, label):
    shutil.copy(SRC, SRC+bak); open(SRC,"w",encoding="utf-8").write(newsrc)
    open("/tmp/_chk.mjs","w",encoding="utf-8").write(newsrc)
    r=subprocess.run(["node","--check","/tmp/_chk.mjs"],capture_output=True,text=True)
    if r.returncode!=0:
        shutil.copy(SRC+bak, SRC); print("HATA node --check (%s):\n%s"%(label,r.stderr)); sys.exit(1)
    print("✓ "+label)

src=open(SRC,encoding="utf-8").read()

# 1) matris CASE
if "WHEN r.grup='FILO TICARI' THEN 'ticari'" in src and "c.ilk_yil >= 2022 AND COALESCE(r.grup,'') <> 'KURUM'" in src:
    print("• matris tip eslemesi zaten Toptan/Ticari.")
elif OLD_MATRIX in src:
    src=src.replace(OLD_MATRIX,NEW_MATRIX,1); apply(src,".bak_mtx","matris CASE → toptan/ticari."); src=open(SRC,encoding="utf-8").read()
else:
    print("HATA: matris CASE bloku bulunamadi — DUR."); sys.exit(1)

# 2) retention-liste → NEW3
if "$3='tumu' AND COALESCE(r.grup,'')<>'KURUM'" in src:
    print("• retention-liste zaten yeni eslemede.")
elif OLD_FAST in src:
    src=src.replace(OLD_FAST,NEW3,1); apply(src,".bak_rl2","retention-liste (hizli) yeni eslemeye cevrildi."); src=open(SRC,encoding="utf-8").read()
elif OLD_SLOW in src:
    src=src.replace(OLD_SLOW,NEW3,1); apply(src,".bak_rl1","retention-liste (yavas) hizli+yeni eslemeye cevrildi."); src=open(SRC,encoding="utf-8").read()
else:
    print("HATA: retention-liste sorgusu bulunamadi — DUR."); sys.exit(1)

# 3) konsantr-liste endpoint
if KMARK in src:
    print("• konsantr-liste endpoint zaten var.")
elif ANCHOR not in src:
    print("HATA: anchor bulunamadi — DUR."); sys.exit(1)
else:
    src=src.replace(ANCHOR, KONS.rstrip()+"\n\n"+ANCHOR, 1); apply(src,".bak_kons","konsantr-liste endpoint eklendi."); src=open(SRC,encoding="utf-8").read()

# 4) shell
html=base64.b64decode("".join(SHELL_B64.split())).decode("utf-8")
os.makedirs(os.path.dirname(SHELLD),exist_ok=True); open(SHELLD,"w",encoding="utf-8").write(html)
print("✓ shell guncellendi (%d bayt) — Toptan/Ticari cipler + export + konsantr + Kokpit link."%len(html))
